// app/gallery/layout.js
export default function GalleryLayout({ children, sidebar }) {
  return (
    <div style={{ display: 'flex' }}>
      <main style={{ flex: 3 }}>{children}</main>
      <aside style={{ flex: 1, borderLeft: '1px solid #ccc', padding: '1rem' }}>
        {sidebar}
      </aside>
    </div>
  );
}

// app/gallery/page.js
import Link from 'next/link';
import { prisma } from '@/lib/prisma';

export default async function Gallery() {
  const photos = await prisma.photo.findMany({ take: 12 });
  return (
    <div className="grid">
      {photos.map(photo => (
        <Link key={photo.id} href={`/photo/${photo.id}`}>
          <img src={photo.url} alt={photo.title} />
        </Link>
      ))}
    </div>
  );
}

// app/gallery/(..)photo/[id]/page.js
import Modal from '@/components/Modal';
import { prisma } from '@/lib/prisma';

export default async function PhotoModal({ params }) {
  const photo = await prisma.photo.findUnique({ where: { id: Number(params.id) } });
  if (!photo) return <div>Not found</div>;
  return (
    <Modal>
      <img src={photo.url} alt={photo.title} />
      <h2>{photo.title}</h2>
    </Modal>
  );
}

// app/photo/[id]/page.js
import { prisma } from '@/lib/prisma';
import { notFound } from 'next/navigation';

export default async function PhotoPage({ params }) {
  const photo = await prisma.photo.findUnique({ where: { id: Number(params.id) } });
  if (!photo) notFound();
  return (
    <div>
      <img src={photo.url} alt={photo.title} />
      <h1>{photo.title}</h1>
    </div>
  );
}

// app/gallery/@sidebar/page.js
import { prisma } from '@/lib/prisma';

export default async function Sidebar() {
  const comments = await prisma.comment.findMany({ take: 5, orderBy: { createdAt: 'desc' } });
  return (
    <div>
      <h3>Recent Comments</h3>
      <ul>
        {comments.map(c => <li key={c.id}>{c.text}</li>)}
      </ul>
    </div>
  );
}
